CREATE DATABASE IF NOT EXISTS smakkita CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smakkita;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','admin') NOT NULL DEFAULT 'student', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL UNIQUE, birth_date DATE NULL, age TINYINT UNSIGNED NULL, domicile VARCHAR(80) NULL, previous_school VARCHAR(180) NULL, education_preference ENUM('sma','smk','undecided') NOT NULL DEFAULT 'undecided', percentile DECIMAL(5,2) NOT NULL DEFAULT 100, admission_path VARCHAR(40) NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE quiz_questions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question VARCHAR(255) NOT NULL, indicator VARCHAR(60) NOT NULL, weight DECIMAL(6,3) NOT NULL DEFAULT 1, order_number INT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE quiz_answers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, question_id INT UNSIGNED NOT NULL, answer TINYINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_answer(student_id,question_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES quiz_questions(id) ON DELETE CASCADE);
CREATE TABLE interest_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, indicator VARCHAR(60) NOT NULL, score DECIMAL(5,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE academic_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL UNIQUE, science DECIMAL(5,2) NOT NULL, social_studies DECIMAL(5,2) NOT NULL, indonesian DECIMAL(5,2) NOT NULL, english DECIMAL(5,2) NOT NULL, mathematics DECIMAL(5,2) NOT NULL, civics DECIMAL(5,2) NOT NULL, academic_average DECIMAL(5,2) NOT NULL, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE academic_achievements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, level_name VARCHAR(30) NOT NULL, organization_type VARCHAR(30) NOT NULL, is_tiered TINYINT(1) NOT NULL DEFAULT 0, rank_number TINYINT UNSIGNED NOT NULL DEFAULT 1, score DECIMAL(5,2) NOT NULL, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE non_academic_achievements LIKE academic_achievements;
CREATE TABLE organization_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL UNIQUE, role_name VARCHAR(30) NOT NULL, score DECIMAL(5,2) NOT NULL, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE school_data (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, npsn VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, address TEXT NOT NULL, domicile VARCHAR(80) NOT NULL, school_type ENUM('SMA','SMK') NOT NULL, average_score DECIMAL(5,2) NULL, capacity INT UNSIGNED NULL, capacity_prestasi_akademik INT UNSIGNED NULL, capacity_prestasi_nonakademik INT UNSIGNED NULL, capacity_tahap_kedua INT UNSIGNED NULL, capacity_afirmasi INT UNSIGNED NULL, capacity_zonasi INT UNSIGNED NULL, accreditation VARCHAR(20) NULL, admission_prestasi_akademik DECIMAL(5,2) NULL, admission_prestasi_nonakademik DECIMAL(5,2) NULL, admission_tahap_kedua DECIMAL(5,2) NULL, admission_afirmasi DECIMAL(5,2) NULL, admission_zonasi DECIMAL(5,2) NULL, source_file VARCHAR(255) NOT NULL, is_active TINYINT(1) DEFAULT 1, INDEX idx_school_type(school_type), INDEX idx_domicile(domicile));
CREATE TABLE school_competencies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, competency VARCHAR(180) NOT NULL, FOREIGN KEY(school_id) REFERENCES school_data(id) ON DELETE CASCADE);
CREATE TABLE majors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, explanation TEXT, priority INT DEFAULT 0, is_active TINYINT(1) DEFAULT 1);
CREATE TABLE major_aliases (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, major_id INT UNSIGNED NOT NULL, alias_name VARCHAR(150) NOT NULL, UNIQUE KEY uq_alias(major_id,alias_name), FOREIGN KEY(major_id) REFERENCES majors(id) ON DELETE CASCADE);
CREATE TABLE recommendations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, model_version VARCHAR(50) NULL, predicted_interest VARCHAR(80) NULL, confidence DECIMAL(6,4) NULL, student_score DECIMAL(6,2) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE recommendation_details (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, recommendation_id BIGINT UNSIGNED NOT NULL, school_id BIGINT UNSIGNED NOT NULL, rank_number INT NOT NULL, score DECIMAL(6,2) NOT NULL, explanation JSON NULL, FOREIGN KEY(recommendation_id) REFERENCES recommendations(id) ON DELETE CASCADE, FOREIGN KEY(school_id) REFERENCES school_data(id));
CREATE TABLE datasets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, file_type VARCHAR(10) NOT NULL, source_path VARCHAR(500) NOT NULL, row_count INT DEFAULT 0, status VARCHAR(30) DEFAULT 'uploaded', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dataset_versions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, dataset_id INT UNSIGNED NOT NULL, version_name VARCHAR(50) NOT NULL, is_active TINYINT(1) DEFAULT 0, FOREIGN KEY(dataset_id) REFERENCES datasets(id) ON DELETE CASCADE);
CREATE TABLE ml_models (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version_name VARCHAR(50) NOT NULL UNIQUE, model_type VARCHAR(80) NOT NULL, dataset_version_id INT UNSIGNED NULL, target_name VARCHAR(100) NOT NULL, features JSON NOT NULL, metrics JSON NULL, model_path VARCHAR(500) NOT NULL, status ENUM('active','archived') DEFAULT 'archived', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(dataset_version_id) REFERENCES dataset_versions(id));
CREATE TABLE training_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ml_model_id INT UNSIGNED NULL, train_count INT NOT NULL, test_count INT NOT NULL, metrics JSON NULL, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ml_model_id) REFERENCES ml_models(id));
CREATE TABLE system_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action_name VARCHAR(100) NOT NULL, detail JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);

USE sma_kita;
CREATE TABLE IF NOT EXISTS passion_professions (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 profession VARCHAR(180) NOT NULL UNIQUE,
 indicator VARCHAR(60) NOT NULL,
 description VARCHAR(255) NULL,
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
